"""ResourcePackServer.java へ Java 1.21.9／1.21.10（プロトコル773）の対応を入れる。

773用パック（pack_format 69、detergentmc-pack-1.21.9.zip）を11番目に増やす。
772の流儀をなぞる：フルコンストラクタを773まで伸ばし、772までの
コンストラクタを「773無し」の委譲版にする。
各アンカーはファイル中にちょうど1回だけ現れること。
"""
import sys
from pathlib import Path

PATH = Path(__file__).resolve().parent.parent / "src" / "main" / "java" \
    / "io" / "detergentmc" / "protocol" / "ResourcePackServer.java"


def edit(path, pairs):
    src = path.read_text(encoding="utf-8")
    for label, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print(f"NG: {label}: anchor が {n} 回見つかった（1回のはず）", file=sys.stderr)
            sys.exit(1)
        src = src.replace(old, new, 1)
        print(f"OK: {label}")
    path.write_text(src, encoding="utf-8")


